<form method="GET" class="course-public-filters" role="search">
    <label>{{ $isSinhala ? 'පාඨමාලා සොයන්න' : 'Search courses' }}<input type="search" name="q" value="{{ $search }}" maxlength="120"></label>
    <label>{{ $isSinhala ? 'වර්ගය' : 'Category' }}<select name="category"><option value="">{{ $isSinhala ? 'සියලු වර්ග' : 'All categories' }}</option>@foreach ($categories as $category)<option value="{{ $category->id }}" @selected((string) $selectedCategory === (string) $category->id)>{{ $isSinhala ? ($category->name_si ?: $category->name) : $category->name }}</option>@endforeach</select></label>
    <label>{{ $isSinhala ? 'තත්ත්වය' : 'Status' }}<select name="status">@foreach (['all' => ['All courses', 'සියලු පාඨමාලා'], 'upcoming' => ['Upcoming', 'ඉදිරියේදී'], 'ongoing' => ['Ongoing', 'දැනට පැවැත්වෙන'], 'completed' => ['Completed', 'අවසන් වූ']] as $value => $label)<option value="{{ $value }}" @selected($selectedStatus === $value)>{{ $label[$isSinhala ? 1 : 0] }}</option>@endforeach</select></label>
    <button type="submit">{{ $isSinhala ? 'සොයන්න' : 'Apply' }}</button>
    <a href="{{ $currentLocale === 'si' ? route('courses.index.localized', ['locale' => 'si']) : route('courses.index') }}">{{ $isSinhala ? 'පෙරහන් ඉවත් කරන්න' : 'Clear filters' }}</a>
</form>
<p class="course-public-count">{{ $isSinhala ? 'පාඨමාලා ගණන:' : 'Courses found:' }} {{ $courses->total() }}</p>
<style>.course-public-filters{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin-bottom:20px}.course-public-filters label{display:grid;gap:6px;font-size:13px}.course-public-filters input,.course-public-filters select,.course-public-filters button{max-width:100%;border:1px solid #cbd5e1;border-radius:8px;padding:10px;background:#fff;font:inherit}.course-public-filters button{background:#145c45;color:#fff}.course-public-count{font-size:13px;color:#475569;margin-bottom:18px}.course-status{display:inline-block;margin-bottom:12px;border-radius:20px;background:#e0f2e9;padding:4px 10px;color:#145c45;font-size:12px}</style>
